def brute_force(root: Optional[TreeNode]) -> None:
    # Inorder -> list, sort a copy, diff the two; then rewrite the tree in inorder. O(n log n).
    def inorder(node: Optional[TreeNode], out: List[TreeNode]) -> None:
        if node:
            inorder(node.left, out)
            out.append(node)
            inorder(node.right, out)

    nodes: List[TreeNode] = []
    inorder(root, nodes)
    target = sorted(n.val for n in nodes)
    for node, want in zip(nodes, target):
        node.val = want                            # only the two swapped positions actually change

def brute_force(root: Optional[TreeNode]) -> int:
    # Try every subset of nodes as camera positions, smallest first: O(2^n * n), exponential.
    nodes: List[TreeNode] = []
    parent = {}

    def collect(node: Optional[TreeNode], par: Optional[TreeNode]) -> None:
        if node:
            nodes.append(node)
            parent[node] = par
            collect(node.left, node)
            collect(node.right, node)

    collect(root, None)
    for k in range(len(nodes) + 1):
        for cams in combinations(nodes, k):
            cam_set = set(cams)
            if all(n in cam_set or parent[n] in cam_set
                   or n.left in cam_set or n.right in cam_set for n in nodes):
                return k
    return 0

