class Solution:
    def wordSquares(self, words: List[str]) -> List[List[str]]:
        n = len(words[0])
        trie: Dict = {"$": list(range(len(words)))}   # the empty prefix (row 0) matches every word
        for i, w in enumerate(words):
            node = trie
            for ch in w:
                node = node.setdefault(ch, {})
                node.setdefault("$", []).append(i)   # every word passing through this prefix

        def candidates(prefix: str) -> List[int]:
            node = trie
            for ch in prefix:
                if ch not in node:
                    return []
                node = node[ch]
            return node.get("$", [])

        squares: List[List[str]] = []
        square: List[str] = []

        def backtrack() -> None:
            k = len(square)
            if k == n:
                squares.append(square[:])
                return
            prefix = "".join(row[k] for row in square)   # column k of the rows so far
            for i in candidates(prefix):
                square.append(words[i])
                backtrack()
                square.pop()

        backtrack()
        return squares

class AutocompleteSystem:
    def __init__(self, sentences: List[str], times: List[int]):
        self.root: Dict = {"$": {}}               # child chars -> node; "$" -> {sentence: count}
        for sentence, count in zip(sentences, times):
            self._add(sentence, count)
        self.cursor: Dict = self.root             # trie node for the prefix typed so far (None = dead)
        self.typed: List[str] = []

    def _add(self, sentence: str, count: int) -> None:
        node = self.root
        for ch in sentence:
            node = node.setdefault(ch, {"$": {}})
            node["$"][sentence] = node["$"].get(sentence, 0) + count   # every prefix node records it

    def input(self, c: str) -> List[str]:
        if c == "#":
            self._add("".join(self.typed), 1)
            self.cursor, self.typed = self.root, []
            return []
        self.typed.append(c)
        if self.cursor is not None:
            self.cursor = self.cursor.get(c)      # one pointer step per keystroke
        if self.cursor is None:
            return []
        top = heapq.nsmallest(3, self.cursor["$"].items(), key=lambda kv: (-kv[1], kv[0]))
        return [sentence for sentence, _ in top]

